async def act(page):
    # Check the current status in the textbox
    status_textbox = page.get_by_role('textbox', name="What's your status?")
    current_status = await status_textbox.input_value()
    if current_status != 'Playing Badminton':
        # Fill the status textbox with 'Playing Badminton'
        await status_textbox.fill('Playing Badminton')
        # Look for a save button to save the changes
        try:
            save_button = page.get_by_role('button', name='Save')
            await save_button.click()
        except:
            try:
                save_button = page.get_by_role('button', name='Save changes')
                await save_button.click()
            except:
                try:
                    save_button = page.get_by_role('button', name='Update profile')
                    await save_button.click()
                except:
                    # If no save button is found, assume auto-save
                    pass
    else:
        # Status is already set to 'Playing Badminton', no action needed
        pass

